def _parse(version):
    """Split a version string into (major, minor, patch, prerelease).

    Build metadata is ignored entirely.  ``prerelease`` is ``None`` when the
    version has no pre-release part, otherwise a list of identifier strings.
    """
    text = version.strip()

    # Build metadata is everything after the first '+' and is ignored.
    plus = text.find('+')
    if plus != -1:
        text = text[:plus]

    # Pre-release is everything after the first '-'.  Identifiers must not be
    # empty, but we tolerate odd input rather than raising.
    pre = None
    dash = text.find('-')
    if dash != -1:
        pre = text[dash + 1:].split('.')
        text = text[:dash]

    parts = text.split('.')
    nums = []
    for i in range(3):
        try:
            nums.append(int(parts[i]))
        except (IndexError, ValueError):
            nums.append(0)

    return nums[0], nums[1], nums[2], pre


def _identifier_key(identifier):
    """Numeric identifiers sort before alphanumeric ones."""
    if identifier.isdigit():
        return (0, int(identifier), '')
    return (1, 0, identifier)


def _sort_key(version):
    major, minor, patch, pre = _parse(version)
    if pre is None:
        # A version without a pre-release outranks any pre-release of the
        # same major/minor/patch.
        pre_key = (1,)
    else:
        pre_key = (0, tuple(_identifier_key(i) for i in pre))
    return (major, minor, patch, pre_key)


def sort_versions(vs):
    """Return ``vs`` sorted by SemVer 2.0.0 precedence, lowest first.

    Ties (including versions differing only in build metadata) preserve their
    original input order, matching a stable sort.
    """
    return sorted(vs, key=_sort_key)
